-- KRIM claims workflow: secure submission, private evidence and independent decisions.
-- Production changes were applied through Supabase SQL; this migration is the reviewed source record.
alter table public.krim_claims
 add column if not exists reviewed_by uuid references auth.users(id) on delete set null,
 add column if not exists reviewed_by_organization_id bigint references public.krim_organizations(id) on delete set null,
 add column if not exists reviewed_at timestamptz;
alter table public.krim_claim_evidence
 add column if not exists storage_path text,
 add column if not exists mime_type text,
 add column if not exists file_size bigint;
create table if not exists public.krim_claim_events(
 id bigint generated by default as identity primary key,
 claim_id bigint not null references public.krim_claims(id) on delete cascade,
 event_type text not null check(event_type in ('submitted','evidence_added','under_review','evidence_required','approved','partially_approved','rejected','closed')),
 actor_user_id uuid references auth.users(id) on delete set null,
 actor_organization_id bigint references public.krim_organizations(id) on delete set null,
 event_note text not null,event_data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()
);
create index if not exists krim_claim_events_claim_created_idx on public.krim_claim_events(claim_id,created_at desc);
create index if not exists krim_claims_claimant_created_idx on public.krim_claims(claimant_organization_id,created_at desc);
create index if not exists krim_claims_respondent_created_idx on public.krim_claims(respondent_organization_id,created_at desc);
alter table public.krim_claim_events enable row level security;
alter table public.krim_claim_events force row level security;
alter table public.krim_claims force row level security;
alter table public.krim_claim_evidence force row level security;
revoke all on public.krim_claim_events from public,anon,authenticated;
grant select on public.krim_claim_events to authenticated;
create policy "KRIM claim events organization access" on public.krim_claim_events for select to authenticated using(
 exists(select 1 from public.krim_claims c where c.id=claim_id and (private.krim_has_organization_access((select auth.uid()),c.organization_id) or (c.respondent_organization_id is not null and private.krim_has_organization_access((select auth.uid()),c.respondent_organization_id))))
);
drop policy if exists "KRIM claims organization access" on public.krim_claims;
create policy "KRIM claims organization access" on public.krim_claims for select to authenticated using(private.krim_has_organization_access((select auth.uid()),organization_id) or (respondent_organization_id is not null and private.krim_has_organization_access((select auth.uid()),respondent_organization_id)));
drop policy if exists "KRIM claim evidence organization access" on public.krim_claim_evidence;
create policy "KRIM claim evidence organization access" on public.krim_claim_evidence for select to authenticated using(exists(select 1 from public.krim_claims c where c.id=claim_id and (private.krim_has_organization_access((select auth.uid()),c.organization_id) or (c.respondent_organization_id is not null and private.krim_has_organization_access((select auth.uid()),c.respondent_organization_id)))));
revoke insert,update,delete on public.krim_claims from public,anon,authenticated;
revoke insert,update,delete on public.krim_claim_evidence from public,anon,authenticated;
revoke insert,update,delete on public.krim_claim_events from public,anon,authenticated;

create or replace function private.krim_claim_submit(p_customer_organization_id bigint,p_shipment_id bigint,p_claim_type text,p_currency_code text,p_claimed_amount numeric,p_description text,p_exception_id bigint default null)
returns bigint language plpgsql security definer set search_path=public,pg_catalog as $function$
declare v_user uuid:=auth.uid();v_customer_org bigint;v_assignment_id bigint;v_partner_org bigint;v_claim_id bigint;v_number text;
begin
 if v_user is null then raise exception 'Authentication required';end if;
 if p_claim_type not in ('loss','damage','delay','shortage','service_failure','billing','other') then raise exception 'Unsupported claim type';end if;
 if p_claimed_amount is null or p_claimed_amount<0 or p_claimed_amount>999999999999 then raise exception 'Invalid claimed amount';end if;
 if length(trim(coalesce(p_description,'')))<20 then raise exception 'Please provide a clear claim description of at least 20 characters';end if;
 if not exists(select 1 from public.krim_organization_members m join public.krim_organizations o on o.id=m.organization_id where m.organization_id=p_customer_organization_id and m.user_id=v_user and m.status='active' and o.status='active' and o.organization_type in ('customer','shipper','enterprise')) then raise exception 'Active customer organization membership required';end if;
 if not private.krim_has_permission(v_user,p_customer_organization_id,'shipment.update') then raise exception 'Customer shipment.update permission required';end if;
 select customer_organization_id into v_customer_org from public.krim_shipments where id=p_shipment_id and status not in ('draft','cancelled','rejected');
 if v_customer_org is null or v_customer_org<>p_customer_organization_id then raise exception 'Shipment is not an active shipment belonging to this customer organization';end if;
 if p_exception_id is not null and not exists(select 1 from public.krim_exceptions e where e.id=p_exception_id and e.shipment_id=p_shipment_id) then raise exception 'Exception does not belong to this shipment';end if;
 if not exists(select 1 from public.krim_currencies where code=upper(p_currency_code) and is_active) then raise exception 'Currency is inactive or unsupported';end if;
 select a.id,a.partner_organization_id into v_assignment_id,v_partner_org from public.krim_shipment_partner_assignments a where a.shipment_id=p_shipment_id and a.status in ('accepted','completed') order by coalesce(a.accepted_at,a.created_at) desc limit 1;
 v_number:='KRIM-CLM-'||to_char(now(),'YYYY')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
 insert into public.krim_claims(organization_id,shipment_id,exception_id,claim_number,claim_type,claimant_organization_id,respondent_organization_id,status,currency_code,claimed_amount,approved_amount,description,submitted_at,metadata,responsible_partner_organization_id,assignment_id)
 values(p_customer_organization_id,p_shipment_id,p_exception_id,v_number,p_claim_type,p_customer_organization_id,v_partner_org,'submitted',upper(p_currency_code),p_claimed_amount,0,left(trim(p_description),10000),now(),jsonb_build_object('submission_channel','customer_workspace'),v_partner_org,v_assignment_id) returning id into v_claim_id;
 insert into public.krim_claim_events(claim_id,event_type,actor_user_id,actor_organization_id,event_note,event_data) values(v_claim_id,'submitted',v_user,p_customer_organization_id,'Customer claim submitted.',jsonb_build_object('claim_type',p_claim_type,'shipment_id',p_shipment_id));
 return v_claim_id;
end;$function$;

create or replace function private.krim_claim_add_evidence(p_claim_id bigint,p_evidence_type text,p_description text,p_storage_path text,p_mime_type text,p_file_size bigint)
returns bigint language plpgsql security definer set search_path=public,storage,pg_catalog as $function$
declare v_user uuid:=auth.uid();v_org bigint;v_status text;v_id bigint;
begin
 if v_user is null then raise exception 'Authentication required';end if;
 if p_evidence_type not in ('photo','invoice','receipt','survey_report','delivery_record','correspondence','other') then raise exception 'Unsupported evidence type';end if;
 if p_mime_type not in ('application/pdf','image/jpeg','image/png') or p_file_size not between 1 and 10485760 then raise exception 'Evidence must be PDF/JPEG/PNG and no larger than 10 MB';end if;
 select organization_id,status into v_org,v_status from public.krim_claims where id=p_claim_id for update;
 if v_org is null then raise exception 'Claim not found';end if;
 if v_status not in ('submitted','under_review','evidence_required') then raise exception 'Claim is not accepting additional evidence';end if;
 if not exists(select 1 from public.krim_organization_members m where m.organization_id=v_org and m.user_id=v_user and m.status='active') or not private.krim_has_permission(v_user,v_org,'shipment.update') then raise exception 'Claimant organization shipment.update permission required';end if;
 if p_storage_path not like 'claim-evidence/'||p_claim_id::text||'/'||v_org::text||'/'||v_user::text||'/%' then raise exception 'Invalid claim evidence storage path';end if;
 if not exists(select 1 from storage.objects o where o.bucket_id='krim-partner-verification' and o.name=p_storage_path and o.owner=v_user and o.metadata->>'mimetype'=p_mime_type and (o.metadata->>'size')::bigint=p_file_size) then raise exception 'Uploaded private evidence not found or metadata mismatch';end if;
 insert into public.krim_claim_evidence(claim_id,evidence_type,description,submitted_by,metadata,verification_status,storage_path,mime_type,file_size)
 values(p_claim_id,p_evidence_type,left(trim(coalesce(p_description,'')),2000),v_user,jsonb_build_object('storage_path',p_storage_path,'mime_type',p_mime_type,'file_size',p_file_size),'pending',p_storage_path,p_mime_type,p_file_size) returning id into v_id;
 insert into public.krim_claim_events(claim_id,event_type,actor_user_id,actor_organization_id,event_note,event_data) values(p_claim_id,'evidence_added',v_user,v_org,'Claim evidence submitted.',jsonb_build_object('evidence_id',v_id,'evidence_type',p_evidence_type));
 return v_id;
end;$function$;

create or replace function private.krim_claim_review(p_claim_id bigint,p_decision text,p_approved_amount numeric,p_note text,p_actor_organization_id bigint)
returns boolean language plpgsql security definer set search_path=public,pg_catalog as $function$
declare v_user uuid:=auth.uid();v_status text;v_claimed numeric;v_org_type text;v_resolved timestamptz;
begin
 if v_user is null then raise exception 'Authentication required';end if;
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception 'Multi-factor authentication required';end if;
 if length(trim(coalesce(p_note,'')))<10 then raise exception 'A meaningful review note of at least 10 characters is required';end if;
 if p_decision not in ('under_review','evidence_required','approved','partially_approved','rejected','closed') then raise exception 'Invalid claim decision';end if;
 select status,claimed_amount into v_status,v_claimed from public.krim_claims where id=p_claim_id for update;
 if v_status is null then raise exception 'Claim not found';end if;
 select organization_type into v_org_type from public.krim_organizations where id=p_actor_organization_id and status='active';
 if v_org_type is null or v_org_type not in ('platform','operations') or not coalesce(private.krim_has_permission(v_user,p_actor_organization_id,'admin.platform'),false) then raise exception 'AAL2 platform administrator permission required';end if;
 if p_decision in ('approved','partially_approved') then
  if p_approved_amount is null or p_approved_amount<=0 or p_approved_amount>v_claimed then raise exception 'Approved amount must be greater than zero and no more than the claimed amount';end if;
 elsif coalesce(p_approved_amount,0)<>0 then raise exception 'Approved amount must be zero unless the claim is approved or partially approved';end if;
 if v_status not in ('submitted','under_review','evidence_required') then raise exception 'Claim is not in a reviewable state';end if;
 v_resolved:=case when p_decision in ('approved','partially_approved','rejected','closed') then now() else null end;
 update public.krim_claims set status=p_decision,approved_amount=coalesce(p_approved_amount,0),decision_reason=left(trim(p_note),2000),decision_at=case when p_decision in ('approved','partially_approved','rejected','closed') then now() else null end,resolved_at=v_resolved,reviewed_by=v_user,reviewed_by_organization_id=p_actor_organization_id,reviewed_at=now(),updated_at=now() where id=p_claim_id;
 insert into public.krim_claim_events(claim_id,event_type,actor_user_id,actor_organization_id,event_note,event_data) values(p_claim_id,p_decision,v_user,p_actor_organization_id,left(trim(p_note),2000),jsonb_build_object('approved_amount',coalesce(p_approved_amount,0)));
 return true;
end;$function$;

create or replace function public.krim_claim_submit(p_customer_organization_id bigint,p_shipment_id bigint,p_claim_type text,p_currency_code text,p_claimed_amount numeric,p_description text,p_exception_id bigint default null)
returns bigint language sql security invoker set search_path=public,pg_catalog as $function$ select private.krim_claim_submit($1,$2,$3,$4,$5,$6,$7); $function$;
create or replace function public.krim_claim_add_evidence(p_claim_id bigint,p_evidence_type text,p_description text,p_storage_path text,p_mime_type text,p_file_size bigint)
returns bigint language sql security invoker set search_path=public,pg_catalog as $function$ select private.krim_claim_add_evidence($1,$2,$3,$4,$5,$6); $function$;
create or replace function public.krim_claim_review(p_claim_id bigint,p_decision text,p_approved_amount numeric,p_note text,p_actor_organization_id bigint)
returns boolean language sql security invoker set search_path=public,pg_catalog as $function$ select private.krim_claim_review($1,$2,$3,$4,$5); $function$;
revoke all on function private.krim_claim_submit(bigint,bigint,text,text,numeric,text,bigint) from public,anon,authenticated;
revoke all on function private.krim_claim_add_evidence(bigint,text,text,text,text,bigint) from public,anon,authenticated;
revoke all on function private.krim_claim_review(bigint,text,numeric,text,bigint) from public,anon,authenticated;
grant execute on function private.krim_claim_submit(bigint,bigint,text,text,numeric,text,bigint) to authenticated;
grant execute on function private.krim_claim_add_evidence(bigint,text,text,text,text,bigint) to authenticated;
grant execute on function private.krim_claim_review(bigint,text,numeric,text,bigint) to authenticated;
revoke all on function public.krim_claim_submit(bigint,bigint,text,text,numeric,text,bigint) from public,anon;
revoke all on function public.krim_claim_add_evidence(bigint,text,text,text,text,bigint) from public,anon;
revoke all on function public.krim_claim_review(bigint,text,numeric,text,bigint) from public,anon;
grant execute on function public.krim_claim_submit(bigint,bigint,text,text,numeric,text,bigint) to authenticated;
grant execute on function public.krim_claim_add_evidence(bigint,text,text,text,text,bigint) to authenticated;
grant execute on function public.krim_claim_review(bigint,text,numeric,text,bigint) to authenticated;

drop policy if exists "KRIM claim evidence upload scoped" on storage.objects;
create policy "KRIM claim evidence upload scoped" on storage.objects for insert to authenticated with check(bucket_id='krim-partner-verification' and split_part(name,'/',1)='claim-evidence' and split_part(name,'/',2) ~ '^[0-9]+$' and split_part(name,'/',3) ~ '^[0-9]+$' and split_part(name,'/',4)=(select auth.uid())::text and owner=(select auth.uid()) and exists(select 1 from public.krim_claims c join public.krim_organization_members m on m.organization_id=c.organization_id where c.id=split_part(name,'/',2)::bigint and c.organization_id=split_part(name,'/',3)::bigint and m.user_id=(select auth.uid()) and m.status='active' and c.status in ('submitted','under_review','evidence_required') and private.krim_has_permission((select auth.uid()),c.organization_id,'shipment.update')));
drop policy if exists "KRIM claim evidence read scoped" on storage.objects;
create policy "KRIM claim evidence read scoped" on storage.objects for select to authenticated using(bucket_id='krim-partner-verification' and split_part(name,'/',1)='claim-evidence' and exists(select 1 from public.krim_claim_evidence e join public.krim_claims c on c.id=e.claim_id where e.storage_path=objects.name and (private.krim_has_organization_access((select auth.uid()),c.organization_id) or (c.respondent_organization_id is not null and private.krim_has_organization_access((select auth.uid()),c.respondent_organization_id)))));
drop policy if exists "KRIM claim evidence admin storage read" on storage.objects;
create policy "KRIM claim evidence admin storage read" on storage.objects for select to authenticated using(bucket_id='krim-partner-verification' and split_part(name,'/',1)='claim-evidence' and exists(select 1 from public.krim_organization_members m join public.krim_organizations o on o.id=m.organization_id where m.user_id=(select auth.uid()) and m.status='active' and o.status='active' and o.organization_type in ('platform','operations') and private.krim_has_permission((select auth.uid()),m.organization_id,'admin.platform')));
drop policy if exists "KRIM claim evidence orphan cleanup" on storage.objects;
create policy "KRIM claim evidence orphan cleanup" on storage.objects for delete to authenticated using(bucket_id='krim-partner-verification' and split_part(name,'/',1)='claim-evidence' and split_part(name,'/',3) ~ '^[0-9]+$' and split_part(name,'/',4)=(select auth.uid())::text and owner=(select auth.uid()) and not exists(select 1 from public.krim_claim_evidence e where e.storage_path=objects.name));
create policy "KRIM claims platform admin read" on public.krim_claims for select to authenticated using(exists(select 1 from public.krim_organization_members m join public.krim_organizations o on o.id=m.organization_id where m.user_id=(select auth.uid()) and m.status='active' and o.status='active' and o.organization_type in ('platform','operations') and private.krim_has_permission((select auth.uid()),m.organization_id,'admin.platform')));
create policy "KRIM claim evidence platform admin read" on public.krim_claim_evidence for select to authenticated using(exists(select 1 from public.krim_organization_members m join public.krim_organizations o on o.id=m.organization_id where m.user_id=(select auth.uid()) and m.status='active' and o.status='active' and o.organization_type in ('platform','operations') and private.krim_has_permission((select auth.uid()),m.organization_id,'admin.platform')));
create policy "KRIM claim events platform admin read" on public.krim_claim_events for select to authenticated using(exists(select 1 from public.krim_organization_members m join public.krim_organizations o on o.id=m.organization_id where m.user_id=(select auth.uid()) and m.status='active' and o.status='active' and o.organization_type in ('platform','operations') and private.krim_has_permission((select auth.uid()),m.organization_id,'admin.platform')));
